// say "action items that I would do", which makes the model drop tasks
// owned by other people ("Priya will send the contract"). Override here so
// it applies to existing modes too.
const ACTION_SECTION_RE = /\baction|follow[- ]?up|next steps?|to-?dos?\b/i;
const ACTION_SECTION_NOTE = ' Include EVERY task anyone committed to or was assigned, whoever owns it (me or anyone else), with or without a deadline. Format each as "Owner: task (due date)" or "Owner: task (no date given)". Never drop an item for lacking a date or for belonging to someone else.';
const sectionList = modeNoteSections
    .map(s => {
        const desc = (s.description?.trim() || '') +
            (ACTION_SECTION_RE.test(s.title) ? ACTION_SECTION_NOTE : '');
        return desc.trim() ? `- "${s.title}": ${desc.trim()}` : `- "${s.title}"`;
    })
    .join('\n');

